```

The `action` builds a mutation and returns a `JsRuleAction` (lines 151-181):
```rust
fn action(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<JsRuleAction> {
    let node = ctx.query();
    let mut mutation = ctx.root().begin();
    // ... build replacement nodes with biome_js_factory::make ...
    mutation.replace_node(node.clone(), /* new node */);
    Some(JsRuleAction {
        mutation,
